-- Politique commerciale actuelle : toute livraison est gratuite à Bamako,
-- sans montant minimum. Cette normalisation garde aussi les nouvelles
-- installations cohérentes avec le panier et la fonction place_order.
update public.settings
set data = jsonb_set(
             jsonb_set(
               jsonb_set(
                 jsonb_set(data, '{deliveryFee}', '0'::jsonb, true),
                 '{deliveryFeeMin}', '0'::jsonb, true
               ),
               '{freeFrom}', '0'::jsonb, true
             ),
             '{announcement}', to_jsonb('Livraison gratuite partout à Bamako'::text), true
           ),
    updated_at = now()
where id = 1;

update public.settings
set data = jsonb_set(
             jsonb_set(
               jsonb_set(
                 data,
                 '{content,hero,sub}',
                 to_jsonb('Des modèles originaux, en pointures 39 à 45. Commande simple par WhatsApp et livraison gratuite partout à Bamako.'::text),
                 true
               ),
               '{content,editorial,pillars,2,title}',
               to_jsonb('Livraison gratuite'::text),
               true
             ),
             '{content,editorial,pillars,2,text}',
             to_jsonb('Partout à Bamako, sans minimum d''achat. Paiement à la livraison, au retrait ou par Orange Money après confirmation.'::text),
             true
           ),
    updated_at = now()
where id = 1;

